<script lang="ts">
	/**
	 * Responsive image for files generated by `npm run images` (static/images/{base}-{w}.{ext}).
	 */
	interface Props {
		base: string;
		alt: string;
		widths: number[];
		width: number;
		height: number;
		sizes?: string;
		/** Formats present for this image; the last one is the <img> fallback. */
		formats?: ('avif' | 'webp' | 'jpg')[];
		loading?: 'lazy' | 'eager';
		fetchpriority?: 'high' | 'low' | 'auto';
		class?: string;
		style?: string;
	}
	let {
		base,
		alt,
		widths,
		width,
		height,
		sizes = '100vw',
		formats = ['avif', 'webp'],
		loading = 'lazy',
		fetchpriority = 'auto',
		class: className = '',
		style
	}: Props = $props();

	const srcset = (ext: string) => widths.map((w) => `/images/${base}-${w}.${ext} ${w}w`).join(', ');
	const fallbackExt = $derived(formats[formats.length - 1] ?? 'webp');
	const largest = $derived(widths[widths.length - 1]);
</script>

<picture>
	{#each formats.slice(0, -1) as ext (ext)}
		<source type="image/{ext}" srcset={srcset(ext)} {sizes} />
	{/each}
	<img
		src="/images/{base}-{largest}.{fallbackExt}"
		srcset={srcset(fallbackExt)}
		{sizes}
		{alt}
		{width}
		{height}
		{loading}
		{fetchpriority}
		decoding="async"
		class={className}
		{style}
	/>
</picture>
